import{_ as t,o as e,c as r,ac as a}from"./chunks/framework.B-3EzaJq.js";const b=JSON.parse('{"title":"六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信","description":"","frontmatter":{"prev":{"text":"十二届四中全会简介","link":"../4/"},"next":{"text":"三十七位老同志请求不再担任中国共产党中央顾问委员会委员致党的十二届四中全会的信","link":"./三十七位老同志请求不再担任中国共产党中央顾问委员会委员致党的十二届四中全会的信"}},"headers":[],"relativePath":"12/4/六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信.md","filePath":"12/4/六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信.md"}'),s={name:"12/4/六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信.md"};function i(n,_,c,o,p,l){return e(),r("div",null,[..._[0]||(_[0]=[a('<h1 id="六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信" tabindex="-1">六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信 <a class="header-anchor" href="#六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信" aria-label="Permalink to &quot;六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信&quot;">​</a></h1><div class="text-center-lg"><p class="sig-text">中国共产党第十二届中央委员会<br>第四次全体会议：</p></div><p>  我们——在这封信上签名的同志们，恳切地请求中央同意我们不再担任第十二届中央委员会的委员和候补委员，以便让一批比较年轻的德才兼备的同志进入中央委员会，进一步实现中央领导机构成员的新老交替。</p><p>  社会主义现代化建设的繁重任务，迫切要求我们的干部队伍，特别是各级领导班子，在革命化的前提下实现年轻化、知识化和专业化。党的十二大已经开始了党中央领导层新老交替的进程。即将召开的党的全国代表会议将继续和加快这一进程。这是这次会议的中心任务，是关系全局的战略决策，我们衷心拥护。我们认为，用自己的实际行动实施这一战略决策，使本届中央委员会在年轻化方面跨进一大步，从而进一步树立干部能上能下的新风气，废除实际上存在的领导职务终身制，形成领导机构成员更新的经常制度，这是我们对党、对共产主义事业应尽的重要责任。</p><p>  我们不再担任中央委员和候补中央委员以后，将继续为党、为人民、为实现共产主义的远大理想努力贡献自己的力量。</p><p>  致共产主义的敬礼！</p><div class="sig-block-a"><div class="sig-content"><p class="sig-text"> 叶剑英 邓颖超 徐向前 聂荣臻 乌兰夫<br> 王 震 韦国清 李德生 宋任穷 张廷发<br> 于 桑 马文瑞 王 谦 王六生 王金山<br> 王恩茂 王鹤寿 白栋材 朱穆之 任仲夷<br> 刘 震 刘华清 刘志坚 刘明辉 刘复之<br> 许家屯 孙大光 孙国治 李 锐 李化民<br> 李启明 杨易辰 肖全夫 汪东兴 张 震<br> 张爱萍 张钰秀 陈伟达 陈国栋 林乎加<br> 周子健 郑三生 赵守一 赵苍壁 胡立教<br> 洪学智 袁宝华 钱学森 铁 瑛 高厚良<br> 黄 华 黄新廷 康克清 梁必业 梁灵光<br> 蒋南翔 韩先楚 覃应机 鲁大东 谢振华<br> 廖汉生 谭友林 谭启龙 谭善和<br> 一九八五年九月 </p></div></div>',7)])])}const m=t(s,[["render",i]]);export{b as __pageData,m as default};
